'use strict';
window.StoryWorld=(()=>{
 const KEY='jumpWorkshopWorld',tiles=new Set(['','ground','brick','pipe','treatbrick','milkbrick','shieldbrick','jumpbrick','firebrick','icebrick','tanukibrick','coin','enemy','spike','plant','turtle','fish','raccoon','switch','redblock','blueblock','swordbrick','bedbox','burgerdirt']);let world;
 const folder=window.FolderSave;
 function readStore(){const disk=folder?.read('world');return disk?JSON.stringify(disk):localStorage.getItem(KEY)}
 function saveStore(value){if(folder?.enabled){try{localStorage.setItem(KEY,JSON.stringify(value))}catch{}folder.write('world',value)}else localStorage.setItem(KEY,JSON.stringify(value))}
 const copy=v=>JSON.parse(JSON.stringify(v)),id=()=>globalThis.crypto?.randomUUID?.()||'chapter-'+Date.now()+'-'+Math.random().toString(36).slice(2);
 function validLevel(l){const width=l?.tiles?.[0]?.length;return l?.version===1&&typeof l.title==='string'&&l.title.length<=60&&Number.isInteger(width)&&width>=60&&width<=720&&Array.isArray(l.tiles)&&l.tiles.length===16&&l.tiles.every(row=>Array.isArray(row)&&row.length===width&&row.every(t=>tiles.has(t)))&&['start','goal'].every(k=>l[k]&&Number.isInteger(l[k].x)&&Number.isInteger(l[k].y)&&l[k].x>=0&&l[k].x<width&&l[k].y>=0&&l[k].y<16)&&(l.theme===undefined||['ground','underwater'].includes(l.theme))}
 const scenery=new Set(['tree','mountain','water','flower','home','road']);
 function validMap(m,levels){if(m===undefined)return true;const ids=new Set(levels.map(c=>c.id)),point=p=>Number.isFinite(p.x)&&p.x>=30&&p.x<=970&&Number.isFinite(p.y)&&p.y>=30&&p.y<=570;return m&&Array.isArray(m.nodes)&&m.nodes.length===levels.length&&new Set(m.nodes.map(n=>n.id)).size===levels.length&&m.nodes.every(n=>ids.has(n.id)&&point(n))&&Array.isArray(m.links)&&m.links.length<=200&&m.links.every(l=>ids.has(l.from)&&ids.has(l.to)&&l.from!==l.to)&&new Set(m.links.map(l=>l.from+'>'+l.to)).size===m.links.length&&Array.isArray(m.decorations)&&m.decorations.length<=300&&m.decorations.every(d=>typeof d.id==='string'&&d.id.length<=100&&scenery.has(d.kind)&&point(d))&&new Set(m.decorations.map(d=>d.id)).size===m.decorations.length&&(m.reference===null||typeof m.reference==='string'&&m.reference.length<=1500000&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(m.reference))&&typeof m.customPaths==='boolean'}
 // A new marker goes to its usual zig-zag spot. If another marker is already there (more than 25 chapters, or a
 // marker was dragged there), it moves to the nearest open spot instead of stacking on top.
 function openSpot(nodes,i){
  const col=i%5,row=Math.floor(i/5),preferred={x:100+(row%2?4-col:col)*200,y:100+(row%5)*100};
  const room=p=>Math.min(Infinity,...nodes.map(n=>Math.max(Math.abs(n.x-p.x)/100,Math.abs(n.y-p.y)/75)));
  if(room(preferred)>=1)return preferred;
  let best=preferred,bestScore=-Infinity;
  for(let y=60;y<=540;y+=80)for(let x=100;x<=900;x+=100){const space=room({x,y}),score=space>=1?-Math.hypot(x-preferred.x,y-preferred.y):space-1e6;if(score>bestScore){best={x,y};bestScore=score}}
  return best;
 }
 function layout(w){
  if(!w.map)w.map={nodes:[],links:[],decorations:[],reference:null,customPaths:false};const m=w.map,ids=new Set(w.levels.map(c=>c.id));m.nodes=m.nodes.filter(n=>ids.has(n.id));
  w.levels.forEach((c,i)=>{if(!m.nodes.some(n=>n.id===c.id))m.nodes.push({id:c.id,...openSpot(m.nodes,i)})});
  m.links=m.links.filter(l=>ids.has(l.from)&&ids.has(l.to));if(!m.customPaths)m.links=w.levels.slice(1).map((c,i)=>({from:w.levels[i].id,to:c.id}));return w;
 }
 function valid(w){return w?.format==='elley-story'&&w.version===1&&typeof w.title==='string'&&w.title.length<=80&&typeof w.intro==='string'&&w.intro.length<=1000&&Array.isArray(w.levels)&&w.levels.length>0&&w.levels.length<=50&&new Set(w.levels.map(l=>l.id)).size===w.levels.length&&w.levels.every(l=>typeof l.id==='string'&&l.id.length>0&&l.id.length<=80&&typeof l.story==='string'&&l.story.length<=1000&&typeof l.complete==='boolean'&&validLevel(l.level))&&validMap(w.map,w.levels)}
 function commit(change){const stored=readStore(),latest=stored?JSON.parse(stored):world;if(!valid(latest))throw Error('The saved story could not be read.');const next=copy(latest);change(next);layout(next);if(!valid(next))throw Error('That story is not valid.');saveStore(next);world=next;return copy(world)}
 function makeLevel(title,chapter){const l={version:1,title,tiles:Array.from({length:16},(_,y)=>Array.from({length:720},()=>y>=14?'ground':'')),start:{x:2,y:13},goal:{x:716,y:13}};for(let section=0;section<12;section++){const off=section*60;if(section<11)for(const x of [35,36,37])l.tiles[14][off+x]=l.tiles[15][off+x]='';for(const [a,b,y]of(chapter===2?[[8,12,11],[20,24,9],[43,47,10]]:[[7,11,11],[18,22,10],[42,46,10]]))for(let x=a;x<=b;x++){l.tiles[y][off+x]='brick';l.tiles[y-1][off+x]='coin'}l.tiles[11][off+8]=section%3===0?'milkbrick':section%3===1?'shieldbrick':'jumpbrick';l.tiles[10][off+20]='treatbrick';for(const x of section===11?[16,28]:[16,28,50])l.tiles[13][off+x]=section%3===1?'turtle':section%3===2?'fish':'enemy'}return l}
 function load(fallback){if(world)return copy(world);const saved=readStore();if(saved){const parsed=JSON.parse(saved);if(!valid(parsed))throw Error('The saved story could not be read. Your stored data has been left untouched.');world=layout(parsed);if(folder?.enabled&&!folder.read('world'))saveStore(parsed);return copy(world)}
 let first=fallback;for(const key of ['jumpWorkshop','jumpWorkshopDraft']){try{const raw=key==='jumpWorkshopDraft'?sessionStorage.getItem(key):localStorage.getItem(key);const candidate=JSON.parse(raw||'null');if(validLevel(candidate))first=candidate}catch{}}
 if(!validLevel(first))first=makeLevel('Sunny-side adventure',1);
 const chapters=[{id:id(),story:'Elley-Oh! sets off on a little adventure. Find a treat for the journey!',level:copy(first),complete:false},{id:id(),story:'The path leads through Caramel Grove. Find milk, grow tall, and get past the caramel chips.',level:makeLevel('Caramel Grove',2),complete:false},{id:id(),story:'The pink house is just ahead! Follow the trail and make it home for a glass of milk.',level:makeLevel('The way home',3),complete:false}];
 const next={format:'elley-story',version:1,title:'Elley-Oh’s journey home',intro:'Every path has a story. Build the chapters together, then help Elley-Oh! find his way home.',selected:chapters[0].id,levels:chapters};layout(next);saveStore(next);world=next;return copy(world)}
 const entry=(w,key)=>{const c=w.levels.find(l=>l.id===key);if(!c)throw Error('That chapter could not be found.');return c};
 // Another tab or browser saved the story: use its copy so this page's next change builds on it.
 if(typeof document!=='undefined')document.addEventListener('folderchange',e=>{if(!world||!e.detail?.keys?.includes('world'))return;const disk=folder?.read('world');if(!valid(disk))return;world=layout(copy(disk));document.dispatchEvent(new Event('storychange'))});
 // Room for 50 chapters plus the largest drawing in an exported (pretty-printed) story file.
 const maxBackupBytes=32*1024*1024;
 return {key:KEY,maxBackupBytes,validLevel,valid,load,get:()=>copy(world),chapter:key=>copy(entry(world,key)),saveLevel(key,l){if(!validLevel(l))throw Error('This course cannot be saved.');return commit(w=>{const c=entry(w,key);if(JSON.stringify([c.level.tiles,c.level.start,c.level.goal,c.level.theme||'ground'])!==JSON.stringify([l.tiles,l.start,l.goal,l.theme||'ground']))c.complete=false;c.level=copy(l);w.selected=key})},select:key=>commit(w=>{entry(w,key);w.selected=key}),complete:key=>commit(w=>{entry(w,key).complete=true}),exits(key){return world.map.links.filter(l=>l.from===key).map(l=>l.to)},next(key){return world.map.links.find(l=>l.from===key)?.to||null},updateMap(map){if(!validMap(map,world.levels))throw Error('That map cannot be saved.');return commit(w=>{w.map=copy(map)})},updateChapter(key,title,story){return commit(w=>{const c=entry(w,key);c.level.title=title;c.story=story})},updateStory(title,intro){return commit(w=>{w.title=title;w.intro=intro})},add(level,story='Write the next part of your story here.'){if(!validLevel(level))throw Error('Choose a valid course file.');const key=id();commit(w=>{if(w.levels.length>=50)throw Error('This story can hold up to 50 chapters.');w.levels.push({id:key,level:copy(level),story,complete:false});w.selected=key});return key},move(key,delta){return commit(w=>{const i=w.levels.findIndex(c=>c.id===key),j=i+delta;if(i<0||j<0||j>=w.levels.length)return;[w.levels[i],w.levels[j]]=[w.levels[j],w.levels[i]]})},remove(key){return commit(w=>{if(w.levels.length===1)throw Error('Keep at least one chapter in the story.');entry(w,key);w.levels=w.levels.filter(c=>c.id!==key);if(w.selected===key)w.selected=w.levels[0].id})},resetProgress(){return commit(w=>w.levels.forEach(c=>c.complete=false))},replace(next){if(!valid(next))throw Error('Choose a valid story backup.');const safe=layout(copy(next));safe.selected=safe.levels.some(c=>c.id===safe.selected)?safe.selected:safe.levels[0].id;saveStore(safe);world=safe;return copy(world)}};
})();
